CREATE TABLE IF NOT EXISTS webhook_subscriptions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),name text NOT NULL,url text NOT NULL,secret_encrypted text NOT NULL,enabled boolean NOT NULL DEFAULT true,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS webhook_outbox(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organization_id uuid NOT NULL REFERENCES organizations(id),subscription_id uuid NOT NULL REFERENCES webhook_subscriptions(id),event_type text NOT NULL,payload jsonb NOT NULL,attempts integer NOT NULL DEFAULT 0,next_attempt_at timestamptz NOT NULL DEFAULT now(),delivered_at timestamptz,dead_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS webhook_due_idx ON webhook_outbox(next_attempt_at) WHERE delivered_at IS NULL AND dead_at IS NULL;
